-- Lugares importantes cerca de algunas estaciones (separados por "; ").
-- Carga inicial con lugares conocidos a pocas cuadras; se puede ampliar.

ALTER TABLE station ADD COLUMN landmarks VARCHAR(300);

UPDATE station s SET landmarks = 'Casa Rosada; Cabildo; Catedral Metropolitana' FROM branch b JOIN transport_line tl ON tl.id = b.transport_line_id WHERE s.branch_id = b.id AND tl.mode = 'SUBTE' AND tl.code = 'A' AND s.name = 'Plaza de Mayo';
